package ama.transcript;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Two distinct real original receipts through production capture/history/proof helpers. */
public final class Task11Fix02DistinctLedgerProbe {
 static final String[] DIMENSIONS={"utf8","scalars","utf16","copyBytes","copyUtf16","maxFactRows","maxFactEdges","responseBytes"};
 public static Map<String,Object> verify(JdbcPublicationService s,ama.contract.IdentityContracts.Actor actor,String meeting,String publication)throws Exception{
  var rows=s.j.queryForList("SELECT e.id,e.operation_id,e.execution_no FROM external_execution e JOIN publication_submission p ON p.task_id=e.task_id WHERE p.publication_id=? AND e.state='FAILED' AND e.marked_at IS NOT NULL AND e.no_effect_basis='DEFINITIVE_REJECTION' ORDER BY p.submission_no",publication);assertEquals(2,rows.size());assertNotEquals(rows.get(0).get("id"),rows.get(1).get("id"));
  var refs=rows.stream().map(r->new PublicationRecordedLookup.Reference((String)r.get("operation_id"),(String)r.get("id"),((Number)r.get("execution_no")).longValue(),new ama.contract.TaskContracts.SubjectRef("MEETING",meeting))).toList();
  long[][] single=new long[2][];var positive=new ArrayList<Map<String,Object>>();
  for(int n=0;n<2;n++){var ledger=ledger(s,-1,0);String receipt=one(s,actor,publication,refs.get(n),ledger);single[n]=ledger.usage();positive.add(Map.of("execution",refs.get(n).executionId(),"receiptId",receipt,"usage",single[n]));}assertNotEquals(positive.get(0).get("receiptId"),positive.get(1).get("receiptId"));
  var combined=ledger(s,-1,0);for(var ref:refs)one(s,actor,publication,ref,combined);long[] combinedUsage=combined.usage();var negatives=new ArrayList<Map<String,Object>>();
  for(int d=0;d<8;d++){
   long limit=Math.max(single[0][d],single[1][d])+1;assertTrue(combinedUsage[d]>limit,"Must be cumulative rather than one oversized receipt");
   for(var ref:refs){var isolated=ledger(s,d,limit);one(s,actor,publication,ref,isolated);assertTrue(isolated.usage()[d]<=limit,"Each distinct receipt independently fits lowered limit");}
   var shared=ledger(s,d,limit);long gets=s.traffic().get("getWriteAttempts");one(s,actor,publication,refs.get(0),shared);long[] beforeSecond=shared.usage();String code;
   if(d==7){var failed=assertThrows(java.io.IOException.class,()->one(s,actor,publication,refs.get(1),shared));assertEquals("PROVIDER_UNAVAILABLE",failed.getMessage());assertEquals(2,s.traffic().get("getWriteAttempts")-gets);assertEquals(beforeSecond[7],shared.usage()[7]);code="PROVIDER_UNAVAILABLE_RESPONSE_BUDGET";}
   else {var failed=assertThrows(ama.contract.MinutesContracts.Failure.class,()->one(s,actor,publication,refs.get(1),shared));assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,failed.code());code=failed.code().name();}
   negatives.add(Map.of("dimension",DIMENSIONS[d],"limit",limit,"individualUsage",List.of(single[0][d],single[1][d]),"combinedPositiveUsage",combinedUsage[d],"firstAccepted",refs.get(0).executionId(),"secondRejected",refs.get(1).executionId(),"beforeSecond",beforeSecond,"afterDenial",shared.usage(),"code",code,"actualGets",s.traffic().get("getWriteAttempts")-gets));
  }
  assertEquals(0L,s.traffic().get("postWriteAttempts"));return Map.of("distinctPositiveReceipts",positive,"combinedPositiveUsage",combinedUsage,"negativeDimensions",negatives,"qualification","Actual production captureReplacement includes complete graph admission and history, then replacementProof validates each exact remote receipt on one ledger. Two distinct recorded executions; manually composed helpers, not a budget-injected full resubmit. Response overflow is translated to IOException by exchange; exact-limit individual controls and unchanged first-response usage establish aggregate boundary.");
 }
 static String one(JdbcPublicationService s,ama.contract.IdentityContracts.Actor actor,String publication,PublicationRecordedLookup.Reference ref,TranscriptAcquisitionBudget.Ledger ledger)throws Exception{var capture=PublicationRecordedLookup.captureReplacement(s,ref,actor,publication,ledger);var receipt=s.replacementProof(capture.identity(),ref.executionId(),ref.executionNo(),ledger);assertEquals(ref.executionId(),receipt.get("executionId"));return (String)receipt.get("receiptId");}
 static TranscriptAcquisitionBudget.Ledger ledger(JdbcPublicationService s,int dimension,long limit)throws Exception{var l=s.limits;var a=s.authority.readBudget();long[] v={l.utf8(),l.scalars(),l.utf16(),l.copyBytes(),l.copyUtf16(),l.responseBytes()};if(dimension>=0&&dimension<5)v[dimension]=limit;else if(dimension==7)v[5]=limit;else if(dimension==5||dimension==6)a=replace(a,DIMENSIONS[dimension],limit);return new TranscriptAcquisitionBudget(v[0],v[1],v[2],v[3],v[4],v[5],l.revisionDepth(),l.revisionNodes(),l.tasks()).ledger(a,s.authority.canonicalBudget(),()->false);}
 @SuppressWarnings("unchecked") static <T>T replace(T record,String field,long value)throws Exception{var components=record.getClass().getRecordComponents();Class<?>[]types=new Class<?>[components.length];Object[]args=new Object[components.length];boolean found=false;for(int i=0;i<components.length;i++){var c=components[i];types[i]=c.getType();args[i]=c.getAccessor().invoke(record);if(c.getName().equals(field)){found=true;if(c.getType()==int.class)args[i]=Math.toIntExact(value);else args[i]=value;}}assertTrue(found);return(T)record.getClass().getDeclaredConstructor(types).newInstance(args);}
}
